import { BooleanColumn, GenericColumn, StringColumn, Table, TableNameColumn } from '../../db'

export const sc_cat_item_producer = Table({
    name: 'sc_cat_item_producer',
    extends: 'sys_metadata',
    schema: {
        allow_edit: BooleanColumn({
            mandatory: false,
            label: 'Allow edit',
            read_only: false,
            active: true,
            default: false,
        }),
        can_cancel: BooleanColumn({
            mandatory: false,
            label: 'Can cancel',
            read_only: false,
            active: true,
            default: false,
        }),
        post_insert_script: GenericColumn({
            mandatory: false,
            label: 'Post insert script',
            read_only: false,
            active: true,
            default:
                '/**\r\n* This script is executed after the record is generated. \r\n* `current` Is the GlideRecord produced by Record Producer. Use `current.update()` to update the record\r\n* To access the variables, use `producer.var1` where var1 is the name of the variable\r\n* To access the Record Producer use `cat_item`\r\n*/',
            column_type: 'script_plain',
        }),
        redirect_url: StringColumn({
            mandatory: false,
            label: 'Redirect to',
            read_only: false,
            active: true,
            default: "javascript: gs.getProperty('glide.sc.producer.redirect_url', 'generated_record')",
            maxLength: 40,
            dropdown: 'dropdown_without_none',
            choices: {
                generated_record: { label: 'Generated task record', sequence: 10, inactive: false, language: 'en' },
                catalog_home: { label: 'Catalog homepage', sequence: 20, inactive: false, language: 'en' },
            },
        }),
        save_options: StringColumn({
            mandatory: false,
            label: 'Save options',
            read_only: false,
            active: true,
            maxLength: 40,
            dropdown: 'dropdown_with_none',
            choices: { destination: { label: 'Save in destination', sequence: 10, inactive: false, language: 'en' } },
        }),
        save_script: GenericColumn({
            mandatory: false,
            label: 'Save script',
            read_only: false,
            active: true,
            default:
                '/**\r\n* This script is executed at every step save in Catalog Builder. \r\n* This script is executed before `Script` is executed.\r\n* `current` Is the GlideRecord produced by Record Producer. \r\n* To access the variables, use `producer.var1` where var1 is the name of the variable\r\n* To access the Record Producer use `cat_item`\r\n*/',
            column_type: 'script_plain',
        }),
        script: GenericColumn({
            mandatory: false,
            label: 'Script',
            read_only: false,
            active: true,
            default:
                "/** This script is executed before the Record is generated\r\n* `current`- GlideRecord produced by Record Producer\r\n* Don't use `current.update()` or `current.insert()` as the record is generated by Record Producer\r\n* Don't use `current.setValue('sys_class_name', 'xxx')` as this will trigger reparent flow and can cause data loss\r\n* Avoid `current.setAbortAction()` and generate a separate record\r\n* Use `producer.var1` to access variables\r\n*/",
            column_type: 'script_plain',
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
        table_name: TableNameColumn({ mandatory: true, label: 'Table name', read_only: false, active: true }),
        view: StringColumn({
            mandatory: false,
            label: 'View',
            read_only: false,
            active: true,
            maxLength: 40,
            dropdown: 'none',
        }),
    },
})
